(function(){function i(e){if(!e)return{morphStyle:"outerHTML"};if(typeof e!=="string")return{morphStyle:"outerHTML"};if(e.includes("innerHTML"))return{morphStyle:"innerHTML"};return{morphStyle:"outerHTML"}}htmx.defineExtension("morph",{isInlineSwap:function(e){let t=i(e);return t?.morphStyle==="outerHTML"||t?.morphStyle==null},handleSwap:function(e,t,n){let r=i(e)||{};r.callbacks=r.callbacks||{};r.callbacks.beforeAttributeUpdated=function(attr){if(attr==="data-active-tab")return false};const scrollMap=new Map();try{if(t.scrollTop>0||t.scrollLeft>0){scrollMap.set(t.id||t,{top:t.scrollTop,left:t.scrollLeft})}t.querySelectorAll("*").forEach(el=>{if(el.scrollTop>0||el.scrollLeft>0){scrollMap.set(el.id||el,{top:el.scrollTop,left:el.scrollLeft})}})}catch(err){}const res=Idiomorph.morph(t,n.children,r);try{scrollMap.forEach((pos,key)=>{const el=typeof key==="string"?(document.getElementById(key)||t.querySelector("#"+key)):key;if(el){if(pos.top>0)el.scrollTop=pos.top;if(pos.left>0)el.scrollLeft=pos.left}})}catch(err){}return res}})})();
